    fields(root,{"schema_family","schema_version","document_id","unit"},{"metadata"});if(str(root,"schema_family")!="frog.execution_ir"||str(root,"schema_version")!="0.1"||str(root,"document_id")!=requirements.documentId)fail("reference_c.fir_version","Exact FIR family/version/identity is required.");
    const auto unit=field(root,"unit");fields(unit,{"id","objects","connections","regions","source_map","correspondence"},{"metadata"});const auto objects=field(unit,"objects").elements();if(objects.empty()||objects.size()>256)fail("reference_c.node_limit","The finite profile admits1..256 FIR objects.");
