            if(n.ports.size()>128||variables>4096)fail("reference_c.port_limit","Finite C admits at most128 ports per object and4096 total.");
            if(n.family=="constant"&&n.kind=="frog.core.constant"){exactPorts(n,{}, {"value"});n.literal=field(attrs,"literal_value");value(*n.literal,n.ports[0].type);const auto profile=str(attrs,"constant_profile");if(profile!="frog.studio.scalar-constant@1"&&profile!="frog.studio.composed-program@1")fail("reference_c.constant_profile","Only the explicitly versioned scalar constant profile is supported.");if(n.ports[0].type==Type::Array)fail("reference_c.constant_profile","Array constants require a separate profile.");}
