    std::set<std::size_t> reached;for(const auto &[region,nodes]:p.order){(void)region;for(auto i:nodes)if(!reached.insert(i).second)fail("reference_c.region","An object is scheduled by multiple owners.",p.nodes[i].id,p.nodes[i].sourcePointer);}if(reached.size()!=p.nodes.size())fail("reference_c.region","A region/object is not reachable from the root owner.");
